    <div
      role="alert"
      data-slot="audio-player-error"
      className="flex min-w-0 flex-1 items-center gap-2"
    >
      <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-4 shrink-0" />
      <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) min-w-0 flex-1 text-pretty">
