      aria-label={label}
      data-slot="audio-player"
      data-variant="default"
      data-audio-state={status === "ready" ? (playing ? "playing" : "paused") : status}
      className={cn(
        "rounded-(--chatcn-radius-xl) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex w-full min-w-0 items-center gap-3 p-3",
