      </div>
      <AudioPlayer
        title="Why the deploy failed"
        meta="Read aloud · Marlo"
        status={preparing ? "loading" : "ready"}
        playing={playing}
        onPlayingChange={setPlaying}
        currentTime={time}
        duration={preparing ? 0 : DURATION}
        onSeek={setTime}
        playbackRate={rate}
        onPlaybackRateChange={setRate}
      />
    </div>
  )
}

